def transform(grid):
    g = np.array(grid)
    bg = background(g)
    floor_rows = {y for y, c in dividers(g)["rows"] if c != bg}
    out = g.copy()
    objs = [o for o in objects(g, bg=bg)
            if not all(y in floor_rows for y, x in o["cells"])]
    # erase all movable objects first
    for o in objs:
        for y, x in o["cells"]:
            out[y, x] = bg
    for o in objs:
        s = o["size"]
        for y, x in o["cells"]:
            ny = y - s
            if 0 <= ny < g.shape[0]:
                out[ny, x] = o["colour"]
        emit(out, f"Move the colour-{o['colour']} object (size {s}) up by {s} rows.")
    emit(out, "Final: every object has risen by its own cell count.")
    return out
